use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [derive (Subcommand)] enum Commands { # [doc = " Generate oracle types and macros"] Generate { # [doc = " Output file for oracle types"] # [arg (short , long , default_value = "src/syscall_oracles.rs")] output : String , } , # [doc = " Transform directory with syscall interception"] Transform { # [doc = " Directory to transform"] # [arg (short , long)] dir : String , # [doc = " Output directory for transformed files"] # [arg (short , long , default_value = "syscall_wrapped")] output : String , # [doc = " Enable mock mode"] # [arg (short , long)] mock : bool , # [doc = " Type safety level"] # [arg (short , long , default_value = "strict")] safety : String , # [doc = " Enable DAO governance"] # [arg (long)] dao : bool , } , # [doc = " Generate default syscall interceptor config"] Config { # [doc = " Output config file"] # [arg (short , long , default_value = "syscall_config.json")] output : String , } , # [doc = " Interactive syscall wrapping"] Interactive { # [doc = " Target directory"] # [arg (short , long , default_value = "output2")] dir : String , } , # [doc = " Analyze syscalls in directory"] Analyze { # [doc = " Directory to analyze"] # [arg (short , long)] dir : String , # [doc = " Generate interceptor config from analysis"] # [arg (short , long)] generate : bool , } , }